// Register (L0) Optimization: Implicit Allocation
int dot_product(const int* A, const int* B, int N) {

    // 'sum' is a candidate for CPU Register residency (L0)
    int sum = 0;

    for (int i = 0; i < N; ++i) {
        // i: loop counter (L0)
        // A[i], B[i]: loaded from higher cache levels (L1/L2) into registers
        sum += A[i] * B[i];
    }
    return sum;
}

// Caching Strategy: Use small, frequently accessed local variables
